import{_ as a,k as s,a6 as i,j as t}from"./chunks/framework.W_BvR9CP.js";const u=JSON.parse('{"title":"v1.3.0","description":"The changelog for v1.3.0.","frontmatter":{"title":"v1.3.0","page_title":"v1.3.0 Changelog","description":"The changelog for v1.3.0.","category":"Releases","nav_order":1,"mentions":["8Crafter"]},"headers":[{"level":2,"title":"Additions","slug":"additions","link":"#additions","children":[{"level":3,"title":"Commands","slug":"commands","link":"#commands","children":[]},{"level":3,"title":"Documentation","slug":"documentation","link":"#documentation","children":[]}]},{"level":2,"title":"Changes","slug":"changes","link":"#changes","children":[{"level":3,"title":"Commands","slug":"commands-1","link":"#commands-1","children":[]}]},{"level":2,"title":"Removals","slug":"removals","link":"#removals","children":[{"level":3,"title":"Commands","slug":"commands-2","link":"#commands-2","children":[]}]},{"level":2,"title":"Fixes","slug":"fixes","link":"#fixes","children":[{"level":3,"title":"Commands","slug":"commands-3","link":"#commands-3","children":[]},{"level":3,"title":"Settings","slug":"settings","link":"#settings","children":[]},{"level":3,"title":"UIs","slug":"uis","link":"#uis","children":[]}]},{"level":2,"title":"Technical Additions","slug":"technical-additions","link":"#technical-additions","children":[{"level":3,"title":"Script Eval Events","slug":"script-eval-events","link":"#script-eval-events","children":[]}]}],"relativePath":"changelogs/v1.3.0.md","filePath":"changelogs/v1.3.0.md"}'),n={name:"changelogs/v1.3.0.md"};function l(o,e,d,h,c,r){return t(),s("div",null,e[0]||(e[0]=[i('<h2 id="additions" tabindex="-1">Additions <a class="header-anchor" href="#additions" aria-label="Permalink to &quot;Additions&quot;">​</a></h2><h3 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h3><ul><li>Added the <a href="./../commands-list/-settings"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\settings</span></code></a> command. This command is used to open the <a href="./../settings/settings">Settings</a> menu. This replaces the old <a href="./../commands-list/-settings_(Old)"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\settings</span></code></a> command.</li></ul><h3 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><ul><li>Added <a href="./../commands-list/-settings"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\settings</span></code></a> and <a href="./../commands-list/-datapickblock"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\datapickblock</span></code></a> to the list of commands shown in the <code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\help</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;"> chatcommands</span></code> subcommand.</li></ul><h2 id="changes" tabindex="-1">Changes <a class="header-anchor" href="#changes" aria-label="Permalink to &quot;Changes&quot;">​</a></h2><h3 id="commands-1" tabindex="-1">Commands <a class="header-anchor" href="#commands-1" aria-label="Permalink to &quot;Commands&quot;">​</a></h3><ul><li>Changed the <a href="./../commands-list/-invsee"><code class="shiki"><span>\\invsee</span></code></a>, <a href="./../commands-list/-offlineinvsee"><code class="shiki"><span>\\offlineinvsee</span></code></a>, and <a href="./../commands-list/-offlineuuidinvsee"><code class="shiki"><span>\\offlineuuidinvsee</span></code></a> commands so that they also display the enchantments of the items.</li><li>Changed the <a href="./../commands-list/-offlineinfo"><code class="shiki"><span>\\offlineinfo</span></code></a> and <a href="./../commands-list/-offlineuuidinfo"><code class="shiki"><span>\\offlineuuidinfo</span></code></a> commands to reset the formatting codes between every property so that if the selected player has an item in their inventory with an obfuscated name, then it won&#39;t cause all the rest of the data to also be obfuscated as well.</li><li>Changed the <a href="./../commands-list/-offlineinvsee"><code class="shiki"><span>\\offlineinvsee</span></code></a> and <a href="./../commands-list/-offlineuuidinvsee"><code class="shiki"><span>\\offlineuuidinvsee</span></code></a> commands to also display the format version that the selected player&#39;s data was saved in.</li></ul><h2 id="removals" tabindex="-1">Removals <a class="header-anchor" href="#removals" aria-label="Permalink to &quot;Removals&quot;">​</a></h2><h3 id="commands-2" tabindex="-1">Commands <a class="header-anchor" href="#commands-2" aria-label="Permalink to &quot;Commands&quot;">​</a></h3><ul><li>Removed the <a href="./../commands-list/-settings_(Old)"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\settings</span></code></a> command as it is mostly useless.</li></ul><h2 id="fixes" tabindex="-1">Fixes <a class="header-anchor" href="#fixes" aria-label="Permalink to &quot;Fixes&quot;">​</a></h2><h3 id="commands-3" tabindex="-1">Commands <a class="header-anchor" href="#commands-3" aria-label="Permalink to &quot;Commands&quot;">​</a></h3><ul><li>Fixed a bug where the <a href="./../commands-list/-run"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\run</span></code></a> command did not run the very first part of the command.</li><li>Fixed a bug where the <a href="./../commands-list/-tint"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\tint</span></code></a> command couldn&#39;t use the target selectors.</li></ul><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><ul><li>Fixed a bug where the option to add a list of chat command prefixes for compatibility other add-ons did not work properly.</li><li>Fixed a bug where the new options to change the prefixes and suffixes for displaying chat ranks and also player names, as well as the custom separator between the player&#39;s name and the message, did not work in a majority of situations, especially for the player name prefixes and suffixes and the separator for the player&#39;s name and message.</li></ul><h3 id="uis" tabindex="-1">UIs <a class="header-anchor" href="#uis" aria-label="Permalink to &quot;UIs&quot;">​</a></h3><ul><li>Fixed a bug where the UI for editing the restricted areas selected the areas for the type of area below the one that you actually selected.</li></ul><h2 id="technical-additions" tabindex="-1">Technical Additions <a class="header-anchor" href="#technical-additions" aria-label="Permalink to &quot;Technical Additions&quot;">​</a></h2><h3 id="script-eval-events" tabindex="-1">Script Eval Events <a class="header-anchor" href="#script-eval-events" aria-label="Permalink to &quot;Script Eval Events&quot;">​</a></h3><ul><li>Added the new custom eval before event dynamic property: <code class="shiki"><span>evalBeforeEvents:chatSendBeforeModifiedMessageSend</span></code>.</li></ul>',21)]))}const f=a(n,[["render",l]]);export{u as __pageData,f as default};
